// Um item por dia (a agenda do iGut só responde dia a dia).
const q = $('Manual').first().json.query || {}, ok = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? s : '';
const ate = ok(q.ate) || $now.minus({ days: 1 }).toISODate(), desde = ok(q.desde) || $now.minus({ days: 365 }).toISODate();
const out = []; for (let d = DateTime.fromISO(desde); d <= DateTime.fromISO(ate) && out.length < 400; d = d.plus({ days: 1 })) out.push({ json: { dia: d.toISODate() } });
return out;

// Só contagens saem daqui (pedido do Jorge de 12/11/2026). Nada de nome, CPF, telefone ou data de nascimento na resposta.
const dias = $('Dias').all().map(i => i.json.dia);
const lista = []; let erros = 0;
const junta = v => { if (Array.isArray(v)) v.forEach(junta); else if (v && typeof v === 'object') { if (v.Agendamento) lista.push(v); else Object.values(v).forEach(x => (Array.isArray(x) || (x && typeof x === 'object')) && junta(x)); } };
for (const i of $input.all()) { if (i.json && i.json.error) erros++; else junta(i.json); }
const acha = (o, re, prof = 0) => { if (!o || typeof o !== 'object' || prof > 3) return undefined; for (const [k, v] of Object.entries(o)) { if (re.test(k) && v !== null && v !== '' && typeof v !== 'object') return v; } for (const v of Object.values(o)) { const r = acha(v, re, prof + 1); if (r !== undefined) return r; } return undefined; };
const camposPac = new Set(); for (const a of lista.slice(0, 200)) Object.keys(a.Paciente || {}).forEach(k => camposPac.add(k));
const nasc = s => { const t = String(s || ''); let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return new Date(+m[1], +m[2] - 1, +m[3]); m = t.match(/^(\d{2})\/(\d{2})\/(\d{4})/); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
const faixa = n => n == null || n < 0 || n > 110 ? 'sem data' : n < 18 ? 'menos de 18' : n < 25 ? '18 a 24' : n < 35 ? '25 a 34' : n < 45 ? '35 a 44' : n < 55 ? '45 a 54' : n < 65 ? '55 a 64' : '65 ou mais';
const genero = v => { const t = String(v || '').trim().toLowerCase(); return /^f|fem/.test(t) ? 'feminino' : /^m|masc/.test(t) ? 'masculino' : 'não informado'; };
// paciente novo: o 1º agendamento de avaliação de cada paciente no período (a chave do paciente só existe em memória)
const novos = new Map();
for (const a of lista.sort((x, y) => String(x.Agendamento?.data).localeCompare(String(y.Agendamento?.data)))) {
  if (!/avalia/i.test(String(a.Agendamento?.tipodeatendimento || ''))) continue;
  const p = a.Paciente || {}, chave = p.id ?? p.codigo ?? p.cpf ?? p.nome; if (chave == null || novos.has(chave)) continue;
  const dn = nasc(acha(p, /nasc/i)), dia = new Date(String(a.Agendamento?.data || '').slice(0, 10) + 'T12:00:00');
  const idade = dn ? Math.floor((dia - dn) / 3.15576e10) : null;
  novos.set(chave, { faixa: faixa(idade), idade, genero: genero(acha(p, /sexo|g[eê]nero/i)), unidade: a.Profissional?.id === 120 || a.Profissional?.id === 121 ? 'Taguatinga' : 'Asa Sul',
    solicitante: acha(a, /solicitante/i) !== undefined, especialidade: String(acha(a, /especialidade/i) || '').trim().toLowerCase(),
    convenio: String(acha(a, /^convenio$|convenio.*nome|^nome_?convenio/i) ?? acha(a.Convenio || {}, /nome|descri/i) ?? '').trim().toUpperCase(),
    cidade: String(acha(p, /cidade/i) || '').trim().toUpperCase() });
}
const ps = [...novos.values()], conta = (f, min = 1) => { const c = {}; for (const p of ps) { const k = f(p) || '(vazio)'; c[k] = (c[k] || 0) + 1; }
  const out = {}, outros = Object.entries(c).filter(([, n]) => n < min).reduce((s, [, n]) => s + n, 0); for (const [k, n] of Object.entries(c).sort((a, b) => b[1] - a[1])) if (n >= min) out[k] = n; if (outros) out['outros (menos de ' + min + ' cada)'] = outros; return out; };
const idades = ps.map(p => p.idade).filter(n => n != null && n >= 0 && n <= 110).sort((a, b) => a - b);
const med = idades.length ? idades[Math.floor(idades.length / 2)] : null;
return [{ json: { periodo: { desde: dias[0], ate: dias[dias.length - 1], dias: dias.length, dias_com_erro: erros }, agendamentos_lidos: lista.length,
  pacientes_novos: ps.length, idade_mediana: med, idade_media: idades.length ? Math.round(idades.reduce((s, n) => s + n, 0) / idades.length) : null,
  faixas: conta(p => p.faixa), genero: conta(p => p.genero), faixas_por_genero: conta(p => p.genero + ' · ' + p.faixa, 3), por_unidade: conta(p => p.unidade),
  com_medico_solicitante: ps.filter(p => p.solicitante).length, especialidade_do_solicitante: conta(p => p.especialidade, 3),
  convenios: conta(p => p.convenio, 3), cidades: conta(p => p.cidade, 5), campos_do_paciente_no_igut: [...camposPac].sort() } }];
